private void mnuItemExportHTML_Click(object sender, EventArgs e)
{
    ExportToHTML();
}

private void ExportToHTML()
{
    if (dtbData == null || dtbData.Rows.Count <= 0)
        return;

    string strTemplate = "MauHTML/BangDiemQuaTrinh.htm";
    string strFileContent = Libs.Files.ReadFile(strTemplate);
    if (strFileContent == null || strFileContent == "")
    {
        MessageManager.Warning("Không tìm thấy file mẫu HTML!");
        return;
    }

    string strHeader1 = SystemService.SYS_SettingService.GetStringValue("Report_Header_Text");
    string strHeader2 = SystemService.SYS_SettingService.GetStringValue("Report_Header2_Text");
    string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
    if (strHeader1 == null || strHeader1 == "")
        strHeader1 = SystemService.SYS_SettingService.GetStringValue("Report_Header");
    if (strHeader2 == null)
        strHeader2 = "";
    if (strPlace == null || strPlace == "")
        strPlace = "TP. HCM";

    string strSubject = "";
    string strFromDate = "";
    string strToDate = "";
    if (uClass.ClassSubject != null && uClass.ClassSubjectIDEditValue != null)
    {
        DataRow[] arrRow = uClass.ClassSubject.Select("ClassSubjectID = " + uClass.ClassSubjectIDEditValue.ToString());
        if (arrRow.Length > 0)
        {
            strSubject = arrRow[0]["SubjectName"].ToString();
            strFromDate = GetDateText(arrRow[0], "FromDate");
            if (strFromDate == "")
                strFromDate = GetDateText(arrRow[0], "BeginDate");
            if (strFromDate == "")
                strFromDate = GetDateText(arrRow[0], "StartDate");
            strToDate = GetDateText(arrRow[0], "ToDate");
            if (strToDate == "")
                strToDate = GetDateText(arrRow[0], "EndDate");
            if (strToDate == "")
                strToDate = GetDateText(arrRow[0], "FinishDate");
        }
    }
    if (strSubject == "")
        strSubject = uClass.SubjectName;

    string strTeacher = "";
    if (objClassSubject != null && objClassSubject.TeachingBy != "")
    {
        BO.SIM_Teacher itemTeacher = new DataAccess.SIM_TeacherDAO().Get(objClassSubject.TeachingBy);
        if (itemTeacher != null)
            strTeacher = itemTeacher.TeacherFirstName + " " + itemTeacher.TeacherLastName;
    }

    DateTime dtmNow = DateTime.Now;
    string strPlaceDate = String.Format("{0}, ngày {1:00} tháng {2:00} năm {3}", strPlace, dtmNow.Day, dtmNow.Month, dtmNow.Year);

    strFileContent = strFileContent.Replace("{HEADER_TEXT}", strHeader1);
    strFileContent = strFileContent.Replace("{HEADER2_TEXT}", strHeader2);
    strFileContent = strFileContent.Replace("{SUBJECT}", strSubject);
    strFileContent = strFileContent.Replace("{FROM_DATE}", strFromDate);
    strFileContent = strFileContent.Replace("{TO_DATE}", strToDate);
    strFileContent = strFileContent.Replace("{TOTAL}", dtbData.Rows.Count.ToString());
    strFileContent = strFileContent.Replace("{PLACE_DATE}", strPlaceDate);
    strFileContent = strFileContent.Replace("{TEACHER}", strTeacher);
    strFileContent = strFileContent.Replace("{DETAIL}", DetailToHTML());

    string strFileNameAs = uClass.ClassIDEditValue + "_BangDiemQuaTrinh.htm";
    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

/// <summary>
/// Dựng các dòng học viên: Họ đệm, Tên, ngày sinh, HS1 (Mark11), HS2 (Mark21). Ô điểm danh để trống.
/// </summary>
private string DetailToHTML()
{
    const int intAttendanceCol = 16;
    string strRows = "";
    int intTT = 1;

    foreach (DataRow drwStudent in dtbData.Rows)
    {
        string strRow = "<tr>"
            + "<td>" + intTT.ToString() + "</td>"
            + "<td class='name first'>" + GetHtmlValue(drwStudent, "StudentFirstName") + "</td>"
            + "<td class='name last'>" + GetHtmlValue(drwStudent, "StudentLastName") + "</td>"
            + "<td>" + GetHtmlValue(drwStudent, "BirthDateText") + "</td>"
            + "<td>" + FormatMarkHTML(GetHtmlValue(drwStudent, "Mark11")) + "</td>"
            + "<td>" + FormatMarkHTML(GetHtmlValue(drwStudent, "Mark21")) + "</td>";

        for (int i = 0; i < intAttendanceCol; i++)
            strRow += "<td class='att'>&nbsp;</td>";

        strRow += "<td>&nbsp;</td></tr>";
        strRows += strRow;
        intTT++;
    }

    return strRows;
}

private string GetHtmlValue(DataRow drw, string strColumn)
{
    if (drw == null || !drw.Table.Columns.Contains(strColumn) || drw[strColumn] == DBNull.Value)
        return "&nbsp;";
    string strValue = drw[strColumn].ToString();
    if (strValue == "")
        return "&nbsp;";
    return strValue;
}

private string GetDateText(DataRow drw, string strColumn)
{
    if (drw == null || !drw.Table.Columns.Contains(strColumn) || drw[strColumn] == DBNull.Value)
        return "";
    string strValue = drw[strColumn].ToString();
    if (strValue == "")
        return "";
    try
    {
        DateTime dtm = Convert.ToDateTime(drw[strColumn]);
        return dtm.ToString("dd/MM/yyyy");
    }
    catch
    {
        return strValue;
    }
}

/// <summary>
/// Hiển thị điểm: -1 -> M, 110 -> Đ, 100 -> CĐ, 10,00 -> 10
/// </summary>
private string FormatMarkHTML(string strValue)
{
    if (strValue == "&nbsp;" || strValue == "")
        return "&nbsp;";
    if (strValue == "-1" || strValue == "-1,0" || strValue == "-10")
        return "M";
    if (strValue == "110")
        return "Đ";
    if (strValue == "100")
        return "CĐ";
    if (strValue == "10,00" || strValue == "10,0" || strValue == "10.00" || strValue == "10.0")
        return "10";
    return strValue;
}

